      sentence = "不过为了避免我的表情泄漏，白警官自己去找，我在这里等你怎么样？",
      next = {79}
    },
    [79] = {
      beijing = 4508,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "白起听闻眨了眨眼，目光在我的脸上转了一圈，不知道在想些什么。",
      next = {80}
    },
    [80] = {
      beijing = 4508,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "不过他很快便直起了身，转了下篮球后塞到了我的手里，在一声“好”中看起来十分自信地出发了。",
      next = {81}
    },
    [81] = {
      beijing = 4508,
      dialog = 3,
      music = "33_Wedding",
      renwu = "npc",
      sentence = "看着他的背影，我想了想，跑到了比分板面前。",
      next = {82}
    },
    [82] = {
      beijing = 4508,
      dhead = 107,
      dialog = 1,
      music = "33_Wedding",
      renming = "$u",
      renwu = "npc",
      sentence = "还好刚刚运气好，找到了粉笔~",
      next = {83}
    },
    [83] = {
      beijing = 4508,
      bganim = 0,
      dialog = 3,
      music = "401_BaiQi",
      renwu = "npc",
      sentence = "本以为白起会找很久，但没想到我只等了一会儿，他就回来了。",
      next = {84}
    },
    [84] = {
      beijing = 4508,
      dhead = 111,
      dialog = 1,
      music = "401_BaiQi",
      renming = "$u",
      renwu = "npc",
      sentence = "不找了吗？",
      next = {85}
    },
    [85] = {
      beijing = 4508,
      dialog = 3,
      music = "401_BaiQi",
      renwu = "npc",
      sentence = "只是一瞬间，他便挑了下眉。眼睛在周围转了一圈，又在不经意间瞥过我的指尖。",
      next = {86}
    },
    [86] = {
      beijing = 4508,
