      idx = 4,
      male = 4,
      music = "401_BaiQi",
      renming = "白起",
      renwu = "npc",
      role1 = 4185000,
      role2 = 403111,
      role3 = 403207,
      role5 = 4185401,
      ruchang = -1,
      sentence = "找。不过要想想。",
      voice = 1,
      next = {87}
    },
    [87] = {
